import{_ as i,o as a,c as e,a2 as t}from"./chunks/framework.doxMM-x8.js";const k=JSON.parse('{"title":"从 Synthetic Publisher 到两个 Lab Viewer","description":"","frontmatter":{"docLocale":"zh","counterpart":"/en/tutorials/synthetic-motion","contentType":"tutorial","prev":false,"next":false},"headers":[],"relativePath":"tutorials/synthetic-motion.md","filePath":"tutorials/synthetic-motion.md"}'),n={name:"tutorials/synthetic-motion.md"};function l(p,s,h,o,r,d){return a(),e("div",null,[...s[0]||(s[0]=[t(`<h1 id="从-synthetic-publisher-到两个-lab-viewer" tabindex="-1">从 Synthetic Publisher 到两个 Lab Viewer <a class="header-anchor" href="#从-synthetic-publisher-到两个-lab-viewer" aria-label="Permalink to &quot;从 Synthetic Publisher 到两个 Lab Viewer&quot;">​</a></h1><p>目标：让一个 Python Synthetic Publisher 驱动两个浏览器中的真实 GLB 对象。两个 Viewer 共用运动数据，分别操作相机和 Inspector。</p><p>先完成<a href="./persistent-world">持久 Lab 与对象</a>与<a href="./persistent-assets">持久数字资产</a>。需要仓库指定的 Node、pnpm、Python 3.10+（包含 venv 与 pip）和桌面浏览器。从仓库根目录执行命令。本文的 Bash 与浏览器验证命令使用 Linux 或 WSL Ubuntu。此教程使用本机 loopback fixture，不需要 GPU、Newton 或 Docker。</p><h2 id="启动独立测试数据" tabindex="-1">启动独立测试数据 <a class="header-anchor" href="#启动独立测试数据" aria-label="Permalink to &quot;启动独立测试数据&quot;">​</a></h2><p>停止先前的开发服务，再启动测试实例：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --frozen-lockfile</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">LAB_WORD_MOTION_FIXTURE</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> LAB_WORD_DATA_DIR</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">.scratch/motion-tutorial-data</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev</span></span></code></pre></div><p>打开 <a href="http://127.0.0.1:5173/lab" target="_blank" rel="noreferrer">http://127.0.0.1:5173/lab</a>。注册一个测试用户，创建名为 <code>Synthetic motion</code> 的 Lab。在资产库导入仓库内的 <code>tests/fixtures/lab/cube.glb</code>，填写名称、来源、许可和版本。将这个资产用于该 Lab 的一个对象，保证它出现在当前 Lab 的资产列表中。</p><ol><li>打开 <strong>合成运动</strong>。</li><li>选择已导入的 GLB，保留 <code>30 Hz</code>。</li><li>点击 <strong>准备并加入测试会话</strong>。</li><li>关闭对话框，观察场景中新增的 20 个模型对象。</li></ol><p>状态先显示等待 Publisher。准备操作只在首次创建时登记 20 个 Entity 和 Scene Node。它保存初始 Placement。每帧运动不会修改这些记录或 Registered Location。</p><p>在同一登录用户的第二个浏览器标签页打开相同 Lab。点击 <strong>合成运动 → 加入已有会话</strong>。第二个 Viewer 可以选择 <code>15 Hz</code>。关闭对话框不会停止运动连接。</p><h2 id="启动-python-publisher" tabindex="-1">启动 Python Publisher <a class="header-anchor" href="#启动-python-publisher" aria-label="Permalink to &quot;启动 Python Publisher&quot;">​</a></h2><p>在 <strong>API 密钥</strong> 页面创建具有 <code>lab:full</code> 的密钥。密钥必须属于创建 fixture 的用户。其他成员可以观看，但不能签发该 fixture 的 Publisher ticket。</p><p>创建独立 Python 环境：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python3</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> venv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .scratch/motion-python</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">.scratch/motion-python/bin/python</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pip</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -r</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tools/synthetic-motion/requirements.txt</span></span></code></pre></div><p>在 Bash 的隐藏输入处输入密钥：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">read</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -rsp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;Lab API key: &#39;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> MOTION_API_KEY</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> MOTION_API_KEY</span></span></code></pre></div><p>查询 Lab 身份。此命令只打印 Lab 名称与 UUID：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">.scratch/motion-python/bin/python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> -</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;PY&#39;</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">import json, os, urllib.request</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">request = urllib.request.Request(&#39;http://127.0.0.1:3000/api/v1/lab/labs&#39;,</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    headers={&#39;Authorization&#39;: &#39;Bearer &#39; + os.environ[&#39;MOTION_API_KEY&#39;]})</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">with urllib.request.urlopen(request, timeout=10) as response:</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    for lab in json.load(response)[&#39;data&#39;]:</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">        print(lab[&#39;name&#39;], lab[&#39;id&#39;])</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">PY</span></span></code></pre></div><p>将 <code>&lt;lab-uuid&gt;</code> 替换为测试 Lab 的 UUID，然后运行：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">.scratch/motion-python/bin/python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs/examples/motion-launch.py</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --lab-id</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">lab-uui</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">d</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --duration</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 600</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">unset</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> MOTION_API_KEY</span></span></code></pre></div><p><a href="https://github.com/CaiZongyuan/labworld/blob/d21b97585cfd2abfa0835086dadabfbf352e47d6/docs/examples/motion-launch.py" target="_blank" rel="noreferrer">启动示例</a>读取 fixture 元数据，通过已认证 HTTP 申请一次性 Publisher ticket，再从 stdin 将 ticket 交给<a href="https://github.com/CaiZongyuan/labworld/blob/d21b97585cfd2abfa0835086dadabfbf352e47d6/tools/synthetic-motion/publisher.py" target="_blank" rel="noreferrer">Publisher</a>。ticket 不出现在命令参数中。Publisher 与 Viewer 使用同一个 Node 监听端口。</p><p>两个浏览器应同时看到 20 个 GLB 对象沿平滑轨迹运动。分别旋转相机、选择对象并打开 Inspector。一个标签页的选择和相机不改变另一个标签页。运行过程中退出第二个 Viewer，再点击 <strong>加入已有会话</strong>。它应直接取得当前完整 Snapshot。</p><h2 id="核对轨迹与边界" tabindex="-1">核对轨迹与边界 <a class="header-anchor" href="#核对轨迹与边界" aria-label="Permalink to &quot;核对轨迹与边界&quot;">​</a></h2><p>Synthetic Publisher 每秒采样 30 次。它发送 20 个 body pose 和 6 个 joint 值。每个完整二进制 Snapshot 是 632 字节。Viewer 使用接收单调时钟与固定仿真速率 <code>1</code>，在有界缓冲内插值。显示帧率与网络消息率是两个计量对象。</p><p>令 <code>t = sim_time_ns / 1e9</code>、<code>phase = i × 0.2</code>，body 索引 <code>i</code> 从 0 到 19：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>x = (i % 5 - 2) × 1.6 + 0.45 × sin(t + phase)</span></span>
<span class="line"><span>y = 0.65 + 0.15 × sin(2 × t + phase)</span></span>
<span class="line"><span>z = (floor(i / 5) - 1.5) × 1.4 + 0.35 × cos(t + phase)</span></span>
<span class="line"><span>yaw = 0.4 × t + i × 0.1</span></span>
<span class="line"><span>joint[j] = 0.5 × sin(t + j × 0.2), j = 0..5</span></span></code></pre></div><p>wire 使用右手系、Y-up、米和 XYZW 四元数。pose 作用于 Scene Node 的世界根位姿。GLB 的居中、贴底 child offset 与固定比例 <code>0.35</code> 保留。<a href="https://github.com/CaiZongyuan/labworld/blob/d21b97585cfd2abfa0835086dadabfbf352e47d6/packages/contracts/src/motion/index.ts" target="_blank" rel="noreferrer">协议源码</a>、<a href="https://github.com/CaiZongyuan/labworld/blob/d21b97585cfd2abfa0835086dadabfbf352e47d6/tools/synthetic-motion/motion_codec.py" target="_blank" rel="noreferrer">Python codec</a>与<a href="https://github.com/CaiZongyuan/labworld/blob/d21b97585cfd2abfa0835086dadabfbf352e47d6/tools/synthetic-motion/synthetic.py" target="_blank" rel="noreferrer">合成轨迹</a>定义可消费的公开合同。</p><p>Gateway 在内存保留当前帧。每 Viewer 只有一个 pending latest slot。它约束实际 WS <code>bufferedAmount</code>：64 KiB 软预算、256 KiB 硬预算；持续阻塞 2 秒的 Viewer 会断开。软预算触发时，该 Viewer 降至 15 Hz。快 Viewer 不等待慢 Viewer。</p><p>fixture 仅在 <code>LAB_WORD_MOTION_FIXTURE=true</code> 且服务监听 loopback 时开放。HTTP 与 WS 都检查真实连接来源，并拒绝带代理转发头的请求。Viewer 使用 30 秒有效的一次性 ticket；WS 准入前没有场景映射。Publisher 身份由独立 ticket 与固定路由确定。</p><p>HTTP DTO 来自 <a href="https://github.com/CaiZongyuan/labworld/blob/d21b97585cfd2abfa0835086dadabfbf352e47d6/packages/server/src/lab/motion/routes.ts" target="_blank" rel="noreferrer">Node 路由</a>的 OpenAPI 生成。高频 pose 不写数据库、<code>world_clock</code> 或 SSE。现有 HTTP 与业务 SSE 保留各自职责。fixture 的绑定随服务停止而结束；已登记对象、资产和初始布局继续保存在测试目录。</p><h2 id="验证源码" tabindex="-1">验证源码 <a class="header-anchor" href="#验证源码" aria-label="Permalink to &quot;验证源码&quot;">​</a></h2><p>安装一次 Chromium，再分别执行短验证与完整验收：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> exec</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> playwright</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> chromium</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test:e2e</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tests/e2e/lab-synthetic-motion.spec.ts</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --grep</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;motion smoke:&#39;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test:e2e</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tests/e2e/lab-synthetic-motion.spec.ts</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --grep</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;motion full:&#39;</span></span></code></pre></div><p>这两个命令使用上面创建的 <code>.scratch/motion-python/bin/python</code>。已有其他独立 Python 环境时，用 <code>MOTION_E2E_PYTHON=/绝对路径/python</code> 指定解释器。运行器会核对已安装的 websockets 与 tracked requirements 中的固定版本。</p><p><a href="https://github.com/CaiZongyuan/labworld/blob/d21b97585cfd2abfa0835086dadabfbf352e47d6/scripts/e2e-server.mjs" target="_blank" rel="noreferrer">motion profile</a>自动构建同源应用，为所属测试后端启用 fixture，并创建独立数据目录、监听端口和 observer 目录。后台 preload 只记录实际 Gateway/WS 计数，不替换值或阻塞目标。浏览器、Publisher 与慢 TCP reader 的 owner 会记录并清理资源；证据保存在 <code>.scratch/vnext-m1/</code> 的本次 run 目录中。</p><p>短验证覆盖真实 Python、两个 GLB Viewer、认证拒绝、原始 wire、Object3D 轨迹、画面曝光及 socket 释放。默认 <code>pnpm test:e2e</code> 与 <code>web-journeys</code> CI 对 motion profile 执行这一项短验证，并保留其他 profile。</p><p><code>motion full:</code> 额外覆盖两个 Viewer 共同 ready 后至少 600 秒、真实慢 TCP 连接、陈旧冻结、独立相机与选择、晚加入、重复切换与资源收敛。它是单独执行的完整验收；默认 suite 的短验证不覆盖这些长测断言。需要记录完整命令、source commit、环境、样本与清理凭据。</p><h2 id="一次失败与恢复" tabindex="-1">一次失败与恢复 <a class="header-anchor" href="#一次失败与恢复" aria-label="Permalink to &quot;一次失败与恢复&quot;">​</a></h2><ol><li>在 Publisher 终端按 Ctrl+C。</li><li>观察两个 Viewer 显示中断或陈旧，并冻结最后可信 pose。</li><li>再次运行隐藏密钥输入和启动命令，取得新的 Publisher ticket 与服务端 epoch。</li><li>观察两个 Viewer 收到新映射握手，再恢复当前 Snapshot。</li></ol><p>Viewer 错误后可点击 <strong>离开运动</strong>，再点击 <strong>加入已有会话</strong>。重用旧 ticket、旧 epoch、重复 sequence 或错误映射应明确失败。Viewer 不会跨 epoch、时间倒退或长缺口插值。</p><p>结束时点击两个 Viewer 的 <strong>离开运动</strong>，停止 Publisher，再停止 <code>pnpm dev</code>。开发 supervisor 会停止所属 Node/Web 进程。测试目录包含本教程的持久资产与对象；需要保留时不要删除它。</p><p>Synthetic 只产生确定性数学轨迹。它不计算物理接触，也不创建生产 Simulation Session 或 Lab Recording。Newton、远程部署和可靠录制属于后续实施范围。</p><p>协议的 TS/Python golden 检查需要系统 Python 3；可用 <code>PYTHON</code> 指定可执行文件。正常 Node/Web 启动和构建不需要 Python。</p><hr><p>源码版本：<code>d21b97585cfd</code> · <a href="https://github.com/CaiZongyuan/labworld/blob/d21b97585cfd2abfa0835086dadabfbf352e47d6/docs/tutorials/synthetic-motion.md" target="_blank" rel="noreferrer">本页 Markdown</a></p>`,45)])])}const b=i(n,[["render",l]]);export{k as __pageData,b as default};
